// Videos 2-4. All figures come from batch1.data.json (generated by calc/batch1.py).
// Scene timings are placeholders until the voice-overs arrive; then they get cues like coffee.ts.
import {Recipe} from '../template';
import d from '../batch1.data.json';
import tCard from './CreditCard.timing.json';
import tFees from './Fees.timing.json';
import t72 from './RuleOf72.timing.json';

// Apply narration timings (from calc/timing.py) to a recipe's scenes, in order.
const timed = (r: Recipe, t: {dur: number; cues: number[]}[], audio: string): Recipe => ({
  ...r, audio, scenes: r.scenes.map((s, i) => ({...s, ...t[i]})),
});

const fmt = (n: number) => '$' + Math.round(n).toLocaleString('en-US');
const CH = 'MONEY, IN DATA';

// ---------- 2. Credit card minimum payments ----------
const c = d.card;
export const creditCard: Recipe = timed({
  id: 'CreditCard',
  thumb: {kicker: 'MINIMUM PAYMENTS ON', from: '$5,000', link: 'takes', to: '19 years', foot: 'and $8,100 in interest'},
  channel: CH,
  scenes: [
    {type: 'hook', dur: 180, kicker: '$5,000 on a credit card', lines: ['Pay the *minimum.*', "How long until\nit's gone?"], question: 'Most people guess a few years.'},
    {
      type: 'people', dur: 330, kicker: 'Same debt. Two plans', footnote: '22% interest a year. No new spending.',
      people: [
        {name: 'Sam', color: 'alert', tag: 'PAYS THE MINIMUM', note: 'Starts at ~$142 a month, shrinking as the balance falls.', statLabel: 'FIRST PAYMENT', stat: fmt(c.first_min)},
        {name: 'Alex', color: 'accent', tag: 'PAYS $200 A MONTH', note: 'Same card, same debt. A fixed $200, every month.', statLabel: 'EVERY MONTH', stat: '$200'},
      ],
    },
    {
      type: 'race', dur: 480, kicker: 'Balance left', xLabel: 'YEARS', xStart: 0, xEnd: 20, xTicks: [0, 5, 10, 15, 20],
      yMax: 5000, yTicks: [0, 1000, 2000, 3000, 4000, 5000],
      series: [
        {name: 'Sam', color: 'alert', data: c.min},
        {name: 'Alex', color: 'accent', data: c.fixed},
      ],
      notes: [
        {at: 3, text: 'Alex: debt-free in\nunder 3 years', x: 5, yValue: 4700, color: 'accent'},
        {at: 12, text: 'Sam is still paying…', x: 9, yValue: 3300, color: 'alert'},
      ],
    },
    {
      type: 'reveal', dur: 330, kicker: 'Interest paid',
      items: [
        {label: `SAM · ${(c.m_min / 12).toFixed(0)} YEARS OF PAYMENTS`, value: fmt(c.int_min), color: 'alert'},
        {label: `ALEX · UNDER ${Math.ceil(c.m_fix / 12)} YEARS`, value: fmt(c.int_fix), color: 'accent'},
      ],
      punch: `Paying less each month\ncost Sam *${fmt(c.int_min - c.int_fix)} more.*`,
    },
    {
      type: 'bars', dur: 300, kicker: 'Where the money went', title: 'The minimum is built\nto *keep you paying.*', max: 13100,
      bars: [
        {label: 'Sam', color: 'alert', base: 5000, extra: c.int_min, caption: `$5,000 debt · ${fmt(c.int_min)} interest`},
        {label: 'Alex', color: 'accent', base: 5000, extra: c.int_fix, caption: `$5,000 debt · ${fmt(c.int_fix)} interest`},
      ],
      body: 'The minimum shrinks as your balance does,\nso your debt *shrinks slowly too.*',
    },
    {
      type: 'outro', dur: 180, lines: 'Pay more than the minimum.\n*Even a little helps.*',
      disclaimer: 'Illustration only: $5,000 balance, 22% APR, no new spending.\nMinimum = interest + 1% of balance (at least $25).\nCard terms vary. Not financial advice.',
    },
  ],
}, tCard, 'audio/CreditCard.mp3');

// ---------- 3. Investment fees ----------
const f = d.fees;
export const fees: Recipe = timed({
  id: 'Fees',
  thumb: {kicker: 'THE REAL COST OF', from: 'a 2% fee', link: 'costs', to: '$98,762', foot: 'over 30 years'},
  channel: CH,
  scenes: [
    {type: 'hook', dur: 180, kicker: 'The quiet cost', lines: ['A *2%* fee', 'sounds tiny.'], question: "Over 30 years, it isn't."},
    {
      type: 'people', dur: 330, kicker: 'Same plan. Different fees', footnote: 'Same markets. Same 7% return before fees.',
      people: [
        {name: 'Alex', color: 'accent', tag: 'LOW-COST FUND · 0.25% A YEAR', note: 'Invests $300 a month for 30 years.', statLabel: 'PUT IN', stat: '$108,000'},
        {name: 'Sam', color: 'paper', tag: 'HIGH-FEE FUND · 2% A YEAR', note: 'Invests the same $300 a month.', statLabel: 'PUT IN', stat: '$108,000'},
      ],
    },
    {
      type: 'race', dur: 480, kicker: 'Watch the gap', xLabel: 'YEARS', xStart: 0, xEnd: 30, xTicks: [0, 10, 20, 30],
      yMax: 400000, yTicks: [0, 100000, 200000, 300000, 400000],
      series: [
        {name: 'Alex · 0.25%', color: 'accent', data: f.low},
        {name: 'Sam · 2%', color: 'paper', data: f.high},
      ],
      notes: [
        {at: 10, text: `Year 10: only ${fmt(f.low['10'] - f.high['10'])} apart`, x: 1, yValue: 370000, color: 'muted'},
        {at: 22, text: 'Then the gap\nkeeps widening', x: 1, yValue: 300000, color: 'alert'},
      ],
    },
    {
      type: 'reveal', dur: 330, kicker: 'After 30 years',
      items: [
        {label: 'ALEX · 0.25% FEES', value: fmt(f.low['30']), color: 'accent'},
        {label: 'SAM · 2% FEES', value: fmt(f.high['30']), color: 'paper'},
      ],
      punch: `A fee that sounded tiny.\n*${fmt(f.low['30'] - f.high['30'])} gone.*`,
    },
    {
      type: 'bars', dur: 300, kicker: 'Where it went', title: "Fees don't just take 2%.\nThey take the *growth* on it.", max: 360000,
      bars: [
        {label: 'Alex', color: 'accent', base: 108000, extra: f.low['30'] - 108000, caption: `$108,000 in · ${fmt(f.low['30'] - 108000)} growth`},
        {label: 'Sam', color: 'paper', base: 108000, extra: f.high['30'] - 108000, caption: `$108,000 in · ${fmt(f.high['30'] - 108000)} growth`},
      ],
      body: 'Check the fee on every fund you own.\nLook for the *expense ratio.*',
    },
    {
      type: 'outro', dur: 180, lines: 'Small fees.\n*Big money.*',
      disclaimer: 'Illustration only: $300 a month, 7% yearly return before fees,\ncompounded monthly, before tax and inflation.\nReal returns vary. Not financial advice.',
    },
  ],
}, tFees, 'audio/Fees.mp3');

// ---------- 4. Rule of 72 ----------
const r = d.r72;
export const ruleOf72: Recipe = timed({
  id: 'RuleOf72',
  thumb: {kicker: 'AT 10% FOR 40 YEARS', from: '$10,000', to: '$452,593', foot: 'the Rule of 72'},
  channel: CH,
  scenes: [
    {type: 'hook', dur: 180, kicker: 'The Rule of 72', lines: ['How fast does\nyour money *double?*'], question: "There's a 5-second trick."},
    {
      type: 'people', dur: 390, kicker: 'Divide 72 by the rate', footnote: "That's roughly how many years it takes to double.",
      people: [
        {name: '72 ÷ 4', color: 'muted', tag: 'AT 4% A YEAR', note: 'Doubles about every 18 years.', statLabel: 'DOUBLES IN', stat: '~18 yrs'},
        {name: '72 ÷ 7', color: 'paper', tag: 'AT 7% A YEAR', note: 'Doubles about every 10 years.', statLabel: 'DOUBLES IN', stat: '~10 yrs'},
        {name: '72 ÷ 10', color: 'accent', tag: 'AT 10% A YEAR', note: 'Doubles about every 7 years.', statLabel: 'DOUBLES IN', stat: '~7 yrs'},
      ],
    },
    {
      type: 'race', dur: 540, kicker: '$10,000 for 40 years', xLabel: 'YEARS', xStart: 0, xEnd: 40, xTicks: [0, 10, 20, 30, 40],
      yMax: 500000, yTicks: [0, 100000, 200000, 300000, 400000, 500000],
      series: [
        {name: '10%', color: 'accent', data: r['10']},
        {name: '7%', color: 'paper', data: r['7']},
        {name: '4%', color: 'muted', data: r['4']},
      ],
      notes: [
        {at: 7, text: '10%: doubled in ~7 years', x: 1, yValue: 460000, color: 'accent'},
        {at: 18, text: '4%: has only doubled once', x: 1, yValue: 390000, color: 'muted'},
      ],
    },
    {
      type: 'reveal', dur: 420, kicker: '$10,000 after 40 years',
      items: [
        {label: 'AT 4%', value: fmt(r['4']['40']), color: 'muted'},
        {label: 'AT 7%', value: fmt(r['7']['40']), color: 'paper'},
        {label: 'AT 10%', value: fmt(r['10']['40']), color: 'accent'},
      ],
      punch: 'Triple the rate.\n*9× the money.*',
    },
    {
      type: 'outro', dur: 180, lines: '72 ÷ your rate.\n*Know your doubling time.*',
      disclaimer: 'Illustration only: steady yearly returns, compounded yearly,\nbefore fees, tax and inflation. The Rule of 72 is an\napproximation. Real returns vary. Not financial advice.',
    },
  ],
}, t72, 'audio/RuleOf72.mp3');
